ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS phone text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS birth_date date;
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS accompaniment_status text NOT NULL DEFAULT 'em_acompanhamento', ADD COLUMN IF NOT EXISTS accompaniment_started_on date, ADD COLUMN IF NOT EXISTS last_access_at timestamptz;
ALTER TABLE public.trainer_settings ADD COLUMN IF NOT EXISTS professional_name text NOT NULL DEFAULT 'William Oliveira', ADD COLUMN IF NOT EXISTS contact_phone text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS pix_key text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS attention_days integer NOT NULL DEFAULT 2, ADD COLUMN IF NOT EXISTS priority_days integer NOT NULL DEFAULT 3, ADD COLUMN IF NOT EXISTS special_days integer NOT NULL DEFAULT 7, ADD COLUMN IF NOT EXISTS suspension_days integer NOT NULL DEFAULT 7, ADD COLUMN IF NOT EXISTS auto_suspend boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS notification_preferences jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS message_templates jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS profile_photo_url text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS logo_url text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS blue_theme text NOT NULL DEFAULT 'classico', ADD COLUMN IF NOT EXISTS public_cta text NOT NULL DEFAULT 'cadastro';
ALTER TABLE public.workout_exercises ADD COLUMN IF NOT EXISTS video_url text;
ALTER TABLE public.plans ALTER COLUMN grace_days SET DEFAULT 7;
UPDATE public.profiles p SET birth_date=a.birth_date FROM public.students s JOIN public.assessments a ON a.student_id=s.id WHERE p.id=s.user_id AND p.birth_date IS NULL;
CREATE TABLE public.student_private_notes(student_id uuid PRIMARY KEY REFERENCES public.students(id) ON DELETE CASCADE, notes text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.student_private_notes TO authenticated; GRANT ALL ON public.student_private_notes TO service_role;
ALTER TABLE public.student_private_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY trainer_private_notes ON public.student_private_notes FOR ALL TO authenticated USING(public.is_trainer_of(student_id)) WITH CHECK(public.is_trainer_of(student_id));
INSERT INTO public.student_private_notes(student_id,notes) SELECT id,coalesce(trainer_notes,'') FROM public.students WHERE trainer_notes IS NOT NULL;
COMMENT ON COLUMN public.students.trainer_notes IS 'DEPRECATED: private observations now use student_private_notes; authenticated SELECT excludes this column.';
REVOKE SELECT ON public.students FROM authenticated;
GRANT SELECT(id,user_id,trainer_id,manual_block,manual_block_reason,manual_block_at,photo_consent_at,data_consent_at,created_at,accompaniment_status,accompaniment_started_on,last_access_at) ON public.students TO authenticated;
REVOKE UPDATE ON public.students FROM authenticated;
CREATE TABLE public.progress_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES public.students(id) ON DELETE CASCADE, measured_on date NOT NULL, weight_kg numeric NOT NULL CHECK(weight_kg>0 AND weight_kg<=600), waist_cm numeric CHECK(waist_cm>0 AND waist_cm<=300), hip_cm numeric CHECK(hip_cm>0 AND hip_cm<=300), chest_cm numeric CHECK(chest_cm>0 AND chest_cm<=300), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=4000), created_at timestamptz NOT NULL DEFAULT now(), recorded_by uuid NOT NULL DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.progress_records TO authenticated; GRANT ALL ON public.progress_records TO service_role;
ALTER TABLE public.progress_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY progress_read ON public.progress_records FOR SELECT TO authenticated USING(public.is_trainer_of(student_id) OR (public.is_own_student(student_id) AND public.student_has_access(student_id)));
CREATE POLICY progress_insert ON public.progress_records FOR INSERT TO authenticated WITH CHECK((public.is_trainer_of(student_id) OR (public.is_own_student(student_id) AND public.student_has_access(student_id))) AND recorded_by=auth.uid());
CREATE POLICY progress_update ON public.progress_records FOR UPDATE TO authenticated USING(public.is_trainer_of(student_id) OR (public.is_own_student(student_id) AND public.student_has_access(student_id))) WITH CHECK(public.is_trainer_of(student_id) OR (public.is_own_student(student_id) AND public.student_has_access(student_id)));
CREATE TABLE public.student_goals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150),description text NOT NULL DEFAULT '',metric text NOT NULL DEFAULT 'personalizada' CHECK(metric IN ('peso','treinos','consistencia','desempenho','personalizada')),initial_value numeric,target_value numeric,due_on date,status text NOT NULL DEFAULT 'em_andamento' CHECK(status IN ('em_andamento','possivel_conquista','alcancada','cancelada')),completed_at timestamptz,confirmed_by uuid,notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.student_goals TO authenticated; GRANT ALL ON public.student_goals TO service_role;
ALTER TABLE public.student_goals ENABLE ROW LEVEL SECURITY;
CREATE POLICY goals_read ON public.student_goals FOR SELECT TO authenticated USING(public.is_trainer_of(student_id) OR (public.is_own_student(student_id) AND public.student_has_access(student_id)));
CREATE POLICY goals_insert ON public.student_goals FOR INSERT TO authenticated WITH CHECK(public.is_trainer_of(student_id) AND status='em_andamento' AND completed_at IS NULL AND confirmed_by IS NULL);
CREATE POLICY goals_update ON public.student_goals FOR UPDATE TO authenticated USING(public.is_trainer_of(student_id)) WITH CHECK(public.is_trainer_of(student_id));
CREATE TABLE public.crm_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trainer_id uuid NOT NULL DEFAULT auth.uid(),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150),email text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',birth_date date,first_contact_on date NOT NULL DEFAULT public.today_br(),source text NOT NULL DEFAULT '',objective text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'novo' CHECK(status IN ('novo','primeiro_contato','aguardando','negociacao','matriculado','nao_convertido')),last_contact_at timestamptz,next_contact_on date,converted_student_id uuid REFERENCES public.students(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_leads TO authenticated; GRANT ALL ON public.crm_leads TO service_role;
ALTER TABLE public.crm_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY leads_owner ON public.crm_leads FOR ALL TO authenticated USING(trainer_id=auth.uid() AND public.has_role(auth.uid(),'admin')) WITH CHECK(trainer_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trainer_id uuid NOT NULL DEFAULT auth.uid(),student_id uuid REFERENCES public.students(id) ON DELETE CASCADE,lead_id uuid REFERENCES public.crm_leads(id) ON DELETE CASCADE,contact_type text NOT NULL CHECK(contact_type IN ('acompanhamento','financeiro','aniversario','meta','comercial','manual','outros')),reason text NOT NULL DEFAULT '',message text NOT NULL DEFAULT '' CHECK(length(message)<=10000),status text NOT NULL DEFAULT 'gerada' CHECK(status IN ('gerada','copiada','enviada','concluida')),notes text NOT NULL DEFAULT '',sent_at timestamptz,birthday_year integer,goal_id uuid REFERENCES public.student_goals(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((student_id IS NOT NULL)::integer+(lead_id IS NOT NULL)::integer=1));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contact_history TO authenticated; GRANT ALL ON public.contact_history TO service_role;
ALTER TABLE public.contact_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_owner ON public.contact_history FOR ALL TO authenticated USING(trainer_id=auth.uid() AND public.has_role(auth.uid(),'admin')) WITH CHECK(trainer_id=auth.uid() AND public.has_role(auth.uid(),'admin') AND ((student_id IS NOT NULL AND public.is_trainer_of(student_id)) OR EXISTS(SELECT 1 FROM public.crm_leads l WHERE l.id=lead_id AND l.trainer_id=auth.uid())));
CREATE UNIQUE INDEX contact_birthday_sent_year ON public.contact_history(student_id,birthday_year) WHERE contact_type='aniversario' AND status IN ('enviada','concluida');
CREATE TABLE public.daily_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trainer_id uuid NOT NULL DEFAULT auth.uid(),action_key text NOT NULL,action_on date NOT NULL DEFAULT public.today_br(),completed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(trainer_id,action_key,action_on));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.daily_actions TO authenticated; GRANT ALL ON public.daily_actions TO service_role;
ALTER TABLE public.daily_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY actions_owner ON public.daily_actions FOR ALL TO authenticated USING(trainer_id=auth.uid() AND public.has_role(auth.uid(),'admin')) WITH CHECK(trainer_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE INDEX progress_student_date ON public.progress_records(student_id,measured_on DESC);
CREATE INDEX contacts_student_date ON public.contact_history(student_id,created_at DESC);
CREATE INDEX leads_trainer_next ON public.crm_leads(trainer_id,next_contact_on);
CREATE OR REPLACE FUNCTION public.settings_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF NEW.attention_days<1 OR NEW.priority_days<NEW.attention_days OR NEW.special_days<NEW.priority_days OR NEW.special_days>365 OR NEW.suspension_days<0 OR NEW.suspension_days>60 THEN RAISE EXCEPTION 'Prazos de acompanhamento inválidos'; END IF;
IF NEW.blue_theme NOT IN ('classico','oceano','eletrico') OR NEW.public_cta NOT IN ('cadastro','contato') THEN RAISE EXCEPTION 'Configuração inválida'; END IF;
NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER settings_validation BEFORE INSERT OR UPDATE ON public.trainer_settings FOR EACH ROW EXECUTE FUNCTION public.settings_guard();
CREATE OR REPLACE FUNCTION public.progress_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.measured_on>public.today_br() THEN RAISE EXCEPTION 'A medição não pode estar no futuro'; END IF; IF TG_OP='UPDATE' AND (NEW.student_id<>OLD.student_id OR NEW.recorded_by<>OLD.recorded_by) THEN RAISE EXCEPTION 'Não é permitido alterar o responsável'; END IF; RETURN NEW; END $$;
CREATE TRIGGER progress_validation BEFORE INSERT OR UPDATE ON public.progress_records FOR EACH ROW EXECUTE FUNCTION public.progress_guard();
CREATE OR REPLACE FUNCTION public.goal_confirmation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='alcancada' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN IF NOT public.is_trainer_of(NEW.student_id) THEN RAISE EXCEPTION 'Apenas o personal pode confirmar'; END IF; NEW.completed_at:=now();NEW.confirmed_by:=auth.uid();PERFORM public.notify((SELECT user_id FROM public.students WHERE id=NEW.student_id),'Meta alcançada',NEW.name,'/aluno/evolucao',NULL); END IF; RETURN NEW; END $$;
CREATE TRIGGER goal_confirmation BEFORE INSERT OR UPDATE ON public.student_goals FOR EACH ROW EXECUTE FUNCTION public.goal_confirmation_guard();
CREATE OR REPLACE FUNCTION public.detect_goal_candidates() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g record; v numeric; tr uuid; valid boolean; BEGIN
FOR g IN SELECT * FROM public.student_goals WHERE student_id=NEW.student_id AND status='em_andamento' AND metric IN ('peso','treinos') LOOP
valid:=false;
IF g.metric='peso' AND TG_TABLE_NAME='progress_records' AND g.initial_value IS NOT NULL AND g.target_value IS NOT NULL AND g.initial_value<>g.target_value THEN SELECT weight_kg INTO v FROM public.progress_records WHERE student_id=g.student_id ORDER BY measured_on DESC,created_at DESC LIMIT 1; valid:=(g.target_value>g.initial_value AND v>=g.target_value) OR (g.target_value<g.initial_value AND v<=g.target_value);
ELSIF g.metric='treinos' AND g.target_value>0 THEN SELECT count(*) INTO v FROM public.training_sessions WHERE student_id=g.student_id AND finished_at IS NOT NULL AND performed_on>=g.created_at::date;valid:=v>=g.target_value; END IF;
IF valid THEN UPDATE public.student_goals SET status='possivel_conquista' WHERE id=g.id;SELECT trainer_id INTO tr FROM public.students WHERE id=g.student_id;PERFORM public.notify(tr,'Meta aguardando confirmação',g.name,'/admin/alunos/'||g.student_id,'goal_candidate_'||g.id);END IF;
END LOOP; RETURN NEW; END $$;
CREATE TRIGGER progress_goal_candidates AFTER INSERT OR UPDATE ON public.progress_records FOR EACH ROW EXECUTE FUNCTION public.detect_goal_candidates();
CREATE TRIGGER training_goal_candidates AFTER UPDATE ON public.training_sessions FOR EACH ROW WHEN (NEW.finished_at IS NOT NULL) EXECUTE FUNCTION public.detect_goal_candidates();
CREATE OR REPLACE FUNCTION public.contacts_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF NEW.status IN ('enviada','concluida') THEN NEW.sent_at:=coalesce(NEW.sent_at,now()); ELSE NEW.sent_at:=NULL; END IF;
IF NEW.contact_type='meta' AND NOT EXISTS(SELECT 1 FROM public.student_goals g WHERE g.id=NEW.goal_id AND g.student_id=NEW.student_id AND g.status='alcancada') THEN RAISE EXCEPTION 'Confirme a conquista antes de parabenizar'; END IF;
NEW.updated_at:=now();RETURN NEW; END $$;
CREATE TRIGGER contact_status_guard BEFORE INSERT OR UPDATE ON public.contact_history FOR EACH ROW EXECUTE FUNCTION public.contacts_guard();
CREATE OR REPLACE FUNCTION public.record_my_access() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso negado';END IF;UPDATE public.students SET last_access_at=now() WHERE user_id=auth.uid();END $$;
REVOKE ALL ON FUNCTION public.record_my_access() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_my_access() TO authenticated;
CREATE OR REPLACE FUNCTION public.update_student_management(_student_id uuid,_status text,_start date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_trainer_of(_student_id) THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF _status NOT IN ('ativo','em_acompanhamento','inativo','suspenso') THEN RAISE EXCEPTION 'Status inválido';END IF;UPDATE public.students SET accompaniment_status=_status,accompaniment_started_on=_start WHERE id=_student_id;PERFORM public.log_audit(_student_id,'cadastro_alterado','students',_student_id,jsonb_build_object('status',_status)); END $$;
REVOKE ALL ON FUNCTION public.update_student_management(uuid,text,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.update_student_management(uuid,text,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.convert_crm_lead(_lead_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.crm_leads;s public.students;BEGIN SELECT * INTO l FROM public.crm_leads WHERE id=_lead_id FOR UPDATE;IF NOT FOUND OR l.trainer_id<>auth.uid() OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso negado';END IF;IF l.converted_student_id IS NOT NULL THEN RETURN l.converted_student_id;END IF;SELECT st.* INTO s FROM public.students st JOIN public.profiles p ON p.id=st.user_id WHERE lower(p.email)=lower(l.email);IF NOT FOUND THEN RAISE EXCEPTION 'Envie o convite para criar a conta do aluno';END IF;IF s.trainer_id IS NOT NULL AND s.trainer_id<>auth.uid() THEN RAISE EXCEPTION 'Conta vinculada a outro personal';END IF;UPDATE public.students SET trainer_id=auth.uid(),accompaniment_status='ativo',accompaniment_started_on=public.today_br() WHERE id=s.id;UPDATE public.profiles SET full_name=l.name,phone=l.phone,birth_date=coalesce(l.birth_date,birth_date) WHERE id=s.user_id;INSERT INTO public.assessments(student_id,full_name,goal_other) VALUES(s.id,l.name,l.objective) ON CONFLICT(student_id) DO NOTHING;UPDATE public.crm_leads SET status='matriculado',converted_student_id=s.id WHERE id=l.id;PERFORM public.log_audit(s.id,'interessado_convertido','crm_leads',l.id,'{}');RETURN s.id;END $$;
REVOKE ALL ON FUNCTION public.convert_crm_lead(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.convert_crm_lead(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_manual_workout(_student_id uuid,_title text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w uuid;v uuid;n integer;BEGIN IF NOT public.is_trainer_of(_student_id) THEN RAISE EXCEPTION 'Acesso negado';END IF;IF length(trim(_title)) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Nome do treino inválido';END IF;PERFORM 1 FROM public.students WHERE id=_student_id FOR UPDATE;SELECT id INTO w FROM public.workouts WHERE student_id=_student_id ORDER BY created_at LIMIT 1;IF w IS NULL THEN INSERT INTO public.workouts(student_id,title,created_by) VALUES(_student_id,trim(_title),auth.uid()) RETURNING id INTO w;END IF;SELECT coalesce(max(version_number),0)+1 INTO n FROM public.workout_versions WHERE workout_id=w;INSERT INTO public.workout_versions(workout_id,student_id,version_number,status,source,summary,created_by) VALUES(w,_student_id,n,'pendente','manual',trim(_title),auth.uid()) RETURNING id INTO v;INSERT INTO public.workout_sessions(version_id,position,name) VALUES(v,0,'Treino A');INSERT INTO public.workout_reviews(version_id,action,reviewer_id) VALUES(v,'criado_manual',auth.uid());PERFORM public.log_audit(_student_id,'treino_manual','workout_versions',v,'{}');RETURN v;END $$;
REVOKE ALL ON FUNCTION public.create_manual_workout(uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.create_manual_workout(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.training_identity_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.performed_on>public.today_br() THEN RAISE EXCEPTION 'Data futura inválida';END IF;IF TG_OP='UPDATE' AND (NEW.student_id<>OLD.student_id OR NEW.version_id<>OLD.version_id OR NEW.session_id<>OLD.session_id OR NEW.started_at<>OLD.started_at) THEN RAISE EXCEPTION 'Identidade da sessão não pode ser alterada';END IF;IF NEW.finished_at IS NOT NULL AND (TG_OP='INSERT' OR OLD.finished_at IS NULL) AND NOT EXISTS(SELECT 1 FROM public.exercise_logs WHERE training_session_id=NEW.id AND completed) THEN RAISE EXCEPTION 'Marque ao menos um exercício realizado';END IF;RETURN NEW;END $$;
CREATE TRIGGER training_identity_validation BEFORE INSERT OR UPDATE ON public.training_sessions FOR EACH ROW EXECUTE FUNCTION public.training_identity_guard();
CREATE OR REPLACE FUNCTION public.sync_assessment_birth() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.profiles SET birth_date=NEW.birth_date WHERE id=(SELECT user_id FROM public.students WHERE id=NEW.student_id);RETURN NEW;END $$;
CREATE TRIGGER assessment_birth_sync AFTER INSERT OR UPDATE OF birth_date ON public.assessments FOR EACH ROW EXECUTE FUNCTION public.sync_assessment_birth();
CREATE OR REPLACE FUNCTION public.new_lead_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.notify(NEW.trainer_id,'Novo interessado cadastrado',NEW.name,'/admin/crm',NULL);RETURN NEW;END $$;
CREATE TRIGGER lead_notification AFTER INSERT ON public.crm_leads FOR EACH ROW EXECUTE FUNCTION public.new_lead_notification();